-- Title: Catalog price-band snapshot for Pricing
-- Kind: patch
-- Intent: pricing_customer_price_rule_s1
-- Context: TH-04 EP02 S1 — provider-owned product/unit/floor contract
-- Touches: _get_product_price_band_snapshot_for_pricing
-- Safety: read-only internal security-definer function; no client execute grant
-- Depends on: 20260713001_catalog_patch_price_band_vat_effective.sql
-- Promoted from _drafts/002_catalog_pricing_price_band_snapshot.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function catalog._get_product_price_band_snapshot_for_pricing(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = catalog, pg_temp
as $$
declare
  v_row record;
  v_minor_units_valid boolean;
begin
  select
    p.id as product_id,
    p.name as product_name,
    p.reference_id as product_reference_id,
    p.sku,
    p.business_status::text as product_status,
    pu.id as product_unit_id,
    pu.unit_name,
    pu.is_active as unit_active,
    coalesce(bp.currency, 'VND') as currency_code,
    pb.list_price_before_vat,
    pb.floor_price_before_vat
  into v_row
  from catalog.products p
  join catalog.product_units pu
    on pu.tenant_id = p.tenant_id
   and pu.product_id = p.id
   and pu.id = p_product_unit_id
  left join catalog.product_unit_price_bands pb
    on pb.tenant_id = p.tenant_id
   and pb.product_id = p.id
   and pb.product_unit_id = pu.id
   and pb.status = 'active'
   and pb.effective_from <= now()
   and (pb.effective_to is null or pb.effective_to > now())
  left join catalog.product_base_price_profiles bp
    on bp.tenant_id = p.tenant_id
   and bp.product_id = p.id
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
    and p.business_status <> 'soft_deleted'::catalog.product_business_status;

  if not found then
    return jsonb_build_object(
      'exists', false,
      'product_id', p_product_id,
      'product_name', '',
      'product_reference_id', null,
      'sku', null,
      'product_unit_id', p_product_unit_id,
      'unit_name', '',
      'sellable_status', 'invalid',
      'sellable', false,
      'currency_code', '',
      'list_price_minor', null,
      'floor_price_minor', null,
      'minor_units_valid', false
    );
  end if;

  v_minor_units_valid :=
    (v_row.list_price_before_vat is null
      or v_row.list_price_before_vat = trunc(v_row.list_price_before_vat))
    and
    (v_row.floor_price_before_vat is null
      or v_row.floor_price_before_vat = trunc(v_row.floor_price_before_vat));

  return jsonb_build_object(
    'exists', true,
    'product_id', v_row.product_id,
    'product_name', v_row.product_name,
    'product_reference_id', v_row.product_reference_id,
    'sku', v_row.sku,
    'product_unit_id', v_row.product_unit_id,
    'unit_name', v_row.unit_name,
    'sellable_status', case
      when v_row.product_status = 'active' and v_row.unit_active then 'active'
      else 'inactive'
    end,
    'sellable', v_row.product_status = 'active' and v_row.unit_active,
    'currency_code', upper(v_row.currency_code),
    'list_price_minor', case
      when v_minor_units_valid then v_row.list_price_before_vat::bigint
      else null
    end,
    'floor_price_minor', case
      when v_minor_units_valid then v_row.floor_price_before_vat::bigint
      else null
    end,
    'minor_units_valid', v_minor_units_valid
  );
end;
$$;

revoke all on function catalog._get_product_price_band_snapshot_for_pricing(
  uuid, uuid, uuid
) from public, anon, authenticated, service_role;
